9	
10	/**
11	 * A client the user tracks: a name and an email. Maps the {@code clients} table (Flyway
12	 * V1__clients.sql); the id is IDENTITY-generated on create.
13	 */
14	@Entity
15	@Table(name = "clients")
16	public class Client {
17	
18	    @Id
19	    @GeneratedValue(strategy = GenerationType.IDENTITY)
20	    private Long id;
21	
22	    @Column(nullable = false)
23	    private String name;
24	
25	    @Column(nullable = false)
26	    private String email;
27	
28	    // Whether the client has been archived (tucked away): an archived client is retained but drops
29	    // off the list and the search. New clients start not-archived (the column default,
30	    // V19__client_archived.sql).
31	    @Column(nullable = false)
32	    private boolean archived;
33	
34	    protected Client() {
35	    }
36	
37	    public Client(String name, String email) {
38	        this.name = name;
39	        this.email = email;
40	    }
41	
42	    public Long getId() {
43	        return id;
44	    }
45	
46	    public String getName() {
47	        return name;
48	    }
49	
50	    public String getEmail() {
51	        return email;
52	    }
53	
