8	/**
9	 * GET /api/dashboard/top-clients — the home screen's leaderboard: the clients that owe the most,
10	 * ranked by how much they owe, capped at the top five. What a client owes is the sum of what is
11	 * still DUE across every invoice their projects hold (each invoice's total minus what has been paid
12	 * against it) — the same derivation {@link GetClientStatement} totals, so the ranking agrees with
13	 * each client's statement. Clients that owe nothing are left off (there is nothing to rank), and
14	 * archived clients drop off here just as they drop off the client list. Ties are broken by client
15	 * id so the order is stable. A cross-entity aggregate read, so it injects the repositories it needs.
16	 * Wired by officefloor/rest/api/dashboard/top-clients.GET.yml.
17	 */
18	public class GetTopClients {
19	
20	    public void service(ClientRepository clients, ProjectRepository projects,
21	            InvoiceRepository invoices, InvoicePaymentRepository payments,
22	            ObjectResponse<List<DashboardTopClientView>> response) {
23	        List<DashboardTopClientView> ranked = clients.findAll().stream()
24	                .filter(client -> !client.isArchived())
25	                .map(client -> new DashboardTopClientView(client.getId(), client.getName(),
